class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        if not digits: return []
        letters = ["abc","def","ghi","jkl","mno","pqrs","tuv","wxyz"]
        out, path = [], []
        def dfs(i: int) -> None:
            if i == len(digits):
                out.append(''.join(path)); return
            for ch in letters[ord(digits[i]) - ord('2')]:
                path.append(ch); dfs(i + 1); path.pop()
        dfs(0)
        return out

import java.util.*;

class Solution {
    private static final String[] LETTERS = {"abc","def","ghi","jkl","mno","pqrs","tuv","wxyz"};
    public List<String> letterCombinations(String digits) {
        List<String> out = new ArrayList<>();
        if (digits.isEmpty()) return out;
        backtrack(digits, 0, new StringBuilder(), out);
        return out;
    }
    private void backtrack(String digits, int i, StringBuilder path, List<String> out) {
        if (i == digits.length()) { out.add(path.toString()); return; }
        String choices = LETTERS[digits.charAt(i) - '2'];
        for (int k = 0; k < choices.length(); k++) {
            path.append(choices.charAt(k)); backtrack(digits, i + 1, path, out); path.deleteCharAt(path.length() - 1);
        }
    }
}

